sys_ui_action.script:
var checkdelivery = new x_hccc_cotl.Hoc_CotlUtils().checkReadyForShipping(current.worksheet, "u_stage=^ORu_stage=preparation^worksheet=", 0);
  var shippingrecord = new x_hccc_cotl.Hoc_CotlUtils().cotlrecordcheck(current,"x_hccc_cotl_shipping");
  var schedulerecord = new x_hccc_cotl.Hoc_CotlUtils().cotlrecordcheck(current,"x_hccc_cotl_colited_scheduled");

  var conditionrelatedlist = (!shippingrecord && !schedulerecord) || current.task_type == 'Telephony' ;
//var conditionrelatedlist = (!shippingrecord) || current.task_type == 'Telephony' ;
  if ((checkdelivery == 'Yes' || current.u_override_shipping) && (conditionrelatedlist)) {
      current.setValue('u_stage', 'shipped');
  }

  if (checkdelivery == 'No' && current.u_override_shipping == false) {
      gs.addErrorMessage('At least one task is not ready for shipped.');
  }

  var worksheetstate = new x_hccc_cotl.Hoc_CotlUtils().checkReadyForShipping(current.worksheet, "u_stageINpreparation,Ready for Shipping^worksheet=", 1);
  if (worksheetstate == 'Yes' && conditionrelatedlist) {
      var works = new GlideRecord('x_hccc_cotl_worksheet');
      if (works.get(current.worksheet.sys_id)) {
          works.stage = 'shipped';
          works.update();
      } else {
          gs.addErrorMessage('Worksheet not found: ' + current.worksheet.sys_id);
      }

  }


  if ((shippingrecord == true) && (current.task_type != 'Telephony')) {

      gs.addErrorMessage('You need to put shipping information in the related list');


  }
 if ((schedulerecord == true) && (current.task_type != 'Telephony')) {

     gs.addErrorMessage('You need to put Scheduled Appointments information in the related list');

}







  current.update();
  action.setRedirectURL(current);
